changeSet.sql:
DO $$
BEGIN
    CREATE EXTENSION IF NOT EXISTS postgis;
EXCEPTION WHEN OTHERS THEN
    -- Образ БД без PostGIS (например managed Postgres на Railway): ниже создаются geo_* на polygon/point.
    NULL;
END $$;

DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_type WHERE typname = 'geo_polygon') THEN
        IF EXISTS (SELECT 1 FROM pg_extension WHERE extname = 'postgis') THEN
            EXECUTE 'CREATE DOMAIN geo_polygon AS geometry(Polygon, 4326)';
        ELSE
            EXECUTE 'CREATE DOMAIN geo_polygon AS polygon';
        END IF;
    END IF;
END $$;

DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_type WHERE typname = 'geo_point') THEN
        IF EXISTS (SELECT 1 FROM pg_extension WHERE extname = 'postgis') THEN
            EXECUTE 'CREATE DOMAIN geo_point AS geography(Point, 4326)';
        ELSE
            EXECUTE 'CREATE DOMAIN geo_point AS point';
        END IF;
    END IF;
END $$;

DO $$ BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_type WHERE typname = 'connection_status') THEN
        CREATE TYPE connection_status AS ENUM ('PENDING', 'ACCEPTED', 'BLOCKED');
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_type WHERE typname = 'document_status') THEN
        CREATE TYPE document_status AS ENUM ('PENDING', 'VERIFIED', 'REJECTED', 'EXPIRED');
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_type WHERE typname = 'transaction_status') THEN
        CREATE TYPE transaction_status AS ENUM ('PENDING', 'COMPLETED', 'FAILED', 'REFUNDED');
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_type WHERE typname = 'transaction_kind') THEN
        CREATE TYPE transaction_kind AS ENUM ('TOP_UP', 'TRIP_PAYMENT', 'SUBSCRIPTION', 'FINE', 'REFUND');
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_type WHERE typname = 'vehicle_status') THEN
        CREATE TYPE vehicle_status AS ENUM ('AVAILABLE', 'IN_USE', 'BOOKED', 'MAINTENANCE', 'UNAVAILABLE');
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_type WHERE typname = 'trip_status') THEN
        CREATE TYPE trip_status AS ENUM ('RESERVED', 'ACTIVE', 'PAUSED', 'COMPLETED', 'CANCELED');
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_type WHERE typname = 'zone_type') THEN
        CREATE TYPE zone_type AS ENUM ('PARKING', 'RESTRICTED', 'SERVICE');
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_type WHERE typname = 'damage_severity') THEN
        CREATE TYPE damage_severity AS ENUM ('MINOR', 'MAJOR', 'CRITICAL');
    END IF;
END $$;
